import type { SessionEvent, SessionSnapshot } from "./types"

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, {
    credentials: "same-origin",
    headers: { "Content-Type": "application/json", ...init?.headers },
    ...init,
  })
  if (!response.ok) throw new Error(`request failed: ${response.status}`)
  return response.json() as Promise<T>
}

export const api = {
  exchange: (token: string) => request<{ authenticated: boolean }>("/api/v1/auth/local/exchange", {
    method: "POST", body: JSON.stringify({ token }),
  }),
  createSession: () => request<{ sessionId: string }>("/api/v1/sessions", {
    method: "POST", body: JSON.stringify({ workingDirectory: "." }),
  }),
  snapshot: (sessionId: string) => request<SessionSnapshot>(`/api/v1/sessions/${sessionId}/snapshot`),
  events: (sessionId: string, after: number, afterStream: number) => request<{ events: SessionEvent[] }>(
    `/api/v1/sessions/${sessionId}/events?after=${after}&afterStream=${afterStream}`,
  ),
  prompt: (sessionId: string, text: string, commandId = crypto.randomUUID()) => request<{ runId: string; acceptedSeq: number }>(`/api/v1/sessions/${sessionId}/prompt`, {
    method: "POST", body: JSON.stringify({ commandId, text }),
  }),
  abort: (sessionId: string) => request<{ cancelled: boolean }>(`/api/v1/sessions/${sessionId}/abort`, { method: "POST" }),
  permission: (permissionId: string, revision: number, decision: "allow" | "deny") => request<{ resolved: boolean }>(
    `/api/v1/permissions/${permissionId}`, { method: "POST", body: JSON.stringify({ revision, decision }) },
  ),
